using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(100)]
    public string Title { get; set; } = string.Empty;

    public string Category { get; set; } = string.Empty;

    [Required, MinLength(1)]
    public string Ingredients { get; set; } = string.Empty;

    [Required, MinLength(1)]
    public string Steps { get; set; } = string.Empty;

    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public static class RecipeStore
{
    private static readonly List<Recipe> Recipes =
    [
        new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F\n2. Roll out dough\n3. Spread crushed tomatoes\n4. Add torn mozzarella\n5. Bake 10-12 minutes\n6. Top with fresh basil and drizzle olive oil" },
        new() { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours\n2. Grill or broil chicken until charred\n3. Sauté garlic and ginger\n4. Add tomato sauce and spices\n5. Simmer 15 minutes\n6. Add cream and chicken, cook 5 more minutes" },
        new() { Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
            Steps = "1. Brown beef in a skillet\n2. Add taco seasoning and water\n3. Simmer until thickened\n4. Warm tortillas\n5. Assemble tacos with toppings" },
        new() { Id = 4, Title = "Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles\nShrimp or tofu\nEggs\nBean sprouts\nGreen onions\nPeanuts\nTamarind paste\nFish sauce\nSugar\nLime",
            Steps = "1. Soak noodles in warm water 30 minutes\n2. Make sauce: tamarind, fish sauce, sugar\n3. Stir-fry protein\n4. Push aside, scramble eggs\n5. Add noodles and sauce\n6. Toss with bean sprouts\n7. Garnish with peanuts, green onions, lime" },
        new() { Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
            Steps = "1. Melt chocolate and butter together\n2. Whisk eggs, sugar, and vanilla\n3. Fold in chocolate mixture\n4. Add flour gently\n5. Pour into greased ramekins\n6. Bake at 425°F for 12-14 minutes\n7. Invert onto plate and serve immediately" },
        new() { Id = 6, Title = "Caesar Salad", Category = "Salads",
            Ingredients = "Romaine lettuce\nParmesan cheese\nCroutons\nAnchovies\nGarlic\nLemon juice\nOlive oil\nEgg yolk\nDijon mustard",
            Steps = "1. Make dressing: blend anchovies, garlic, lemon, egg yolk, mustard, oil\n2. Chop romaine\n3. Toss with dressing\n4. Top with shaved parmesan and croutons" },
    ];

    private static readonly Dictionary<int, List<int>> Ratings = new();

    public static IReadOnlyList<Recipe> GetAll() => Recipes.AsReadOnly();

    public static IEnumerable<Recipe> GetByCategory(string category) =>
        Recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase));

    public static Recipe? GetById(int id) => Recipes.FirstOrDefault(r => r.Id == id);

    public static IEnumerable<string> GetCategories() =>
        Recipes.Select(r => r.Category).Distinct().OrderBy(c => c);

    public static void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        if (!Ratings.ContainsKey(recipeId))
            Ratings[recipeId] = [];
        Ratings[recipeId].Add(stars);

        var recipe = GetById(recipeId);
        if (recipe is not null)
        {
            recipe.RatingCount = Ratings[recipeId].Count;
            recipe.AverageRating = Ratings[recipeId].Average();
        }
    }

    public static void Add(Recipe recipe)
    {
        recipe.Id = Recipes.Count > 0 ? Recipes.Max(r => r.Id) + 1 : 1;
        Recipes.Add(recipe);
    }
}

@page "/recipes/{Category}"
@using RecipeShare.Models

<PageTitle>@Category Recipes - RecipeShare</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@Category</li>
        </ol>
    </nav>

    <h1 class="mb-4">@Category Recipes</h1>

    @if (!recipes.Any())
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
    else
    {
        <div class="row g-3">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            @if (recipe.RatingCount > 0)
                            {
                                <p class="text-warning mb-1">
                                    @for (int i = 1; i <= 5; i++)
                                    {
                                        <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                                    }
                                    <small class="text-muted">(@recipe.RatingCount ratings)</small>
                                </p>
                            }
                            <a href="/recipe/@recipe.Id" class="btn btn-outline-primary btn-sm">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    private IEnumerable<Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeStore.GetByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Models

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/recipes/@recipe.Category.ToLower()">@recipe.Category</a></li>
                <li class="breadcrumb-item active">@recipe.Title</li>
            }
        </ol>
    </nav>

    @if (recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1 class="mb-3">@recipe.Title</h1>
        <span class="badge bg-secondary mb-3">@recipe.Category</span>

        <div class="card mb-4">
            <div class="card-header"><h5 class="mb-0">⭐ Rate this Recipe</h5></div>
            <div class="card-body">
                <StarRating RecipeId="@recipe.Id" @rendermode="InteractiveServer" />
            </div>
        </div>

        <div class="row">
            <div class="col-md-4">
                <div class="card mb-4">
                    <div class="card-header"><h5 class="mb-0">📋 Ingredients</h5></div>
                    <div class="card-body">
                        <ul class="list-unstyled mb-0">
                            @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                            {
                                <li class="mb-1">• @ingredient</li>
                            }
                        </ul>
                    </div>
                </div>
            </div>
            <div class="col-md-8">
                <div class="card mb-4">
                    <div class="card-header"><h5 class="mb-0">👨‍🍳 Steps</h5></div>
                    <div class="card-body">
                        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <p class="mb-2">@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeStore.GetById(Id);
    }
}

@using RecipeShare.Models

<div class="d-flex align-items-center gap-2">
    <div class="star-rating" style="font-size: 1.5rem; cursor: pointer;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="@(star <= (hoveredStar > 0 ? hoveredStar : selectedStar) ? "text-warning" : "text-muted")"
                  @onmouseover="() => hoveredStar = star"
                  @onmouseout="() => hoveredStar = 0"
                  @onclick="() => Rate(star)"
                  role="button"
                  aria-label="@star stars">★</span>
        }
    </div>

    @if (submitted)
    {
        <span class="text-success fw-bold">Thanks for rating!</span>
    }

    @if (recipe is not null && recipe.RatingCount > 0)
    {
        <small class="text-muted ms-2">
            Average: @recipe.AverageRating.ToString("F1") / 5 (@recipe.RatingCount ratings)
        </small>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int hoveredStar;
    private int selectedStar;
    private bool submitted;
    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeStore.GetById(RecipeId);
    }

    private void Rate(int stars)
    {
        selectedStar = stars;
        RecipeStore.AddRating(RecipeId, stars);
        recipe = RecipeStore.GetById(RecipeId);
        submitted = true;
    }
}

@page "/submit"
@using RecipeShare.Models
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1 class="mb-4">📝 Submit a Recipe</h1>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4>Recipe submitted successfully!</h4>
            <p>Your recipe "<strong>@newRecipe.Title</strong>" has been added.</p>
            <a href="/recipe/@newRecipe.Id" class="btn btn-primary">View Recipe</a>
            <button class="btn btn-outline-secondary ms-2" @onclick="Reset">Submit Another</button>
        </div>
    }
    else
    {
        <EditForm Model="@newRecipe" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="newRecipe.Title"
                           placeholder="e.g., Grandma's Apple Pie" />
                <ValidationMessage For="@(() => newRecipe.Title)" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="newRecipe.Category">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeStore.GetCategories())
                    {
                        <option value="@cat">@cat</option>
                    }
                    <option value="Other">Other</option>
                </InputSelect>
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="5"
                               @bind-Value="newRecipe.Ingredients"
                               placeholder="One ingredient per line" />
                <ValidationMessage For="@(() => newRecipe.Ingredients)" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" class="form-control" rows="6"
                               @bind-Value="newRecipe.Steps"
                               placeholder="Describe each step" />
                <ValidationMessage For="@(() => newRecipe.Steps)" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    private Recipe newRecipe = new();
    private bool submitted;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(newRecipe.Category))
            newRecipe.Category = "Other";

        RecipeStore.Add(newRecipe);
        submitted = true;
    }

    private void Reset()
    {
        newRecipe = new();
        submitted = false;
    }
}

